<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
$id = max(0, (int)($_GET['id'] ?? $_POST['id'] ?? 0));
$siswa = siswa_find($pdo, $id);
if (!$siswa) { http_response_code(404); exit('Siswa tidak ditemukan.'); }
$errors=[];
$nis=trim((string)($_POST['nis'] ?? $siswa['nis'])); $nisn=trim((string)($_POST['nisn'] ?? ($siswa['nisn'] ?? ''))); $nama=trim((string)($_POST['nama'] ?? $siswa['nama'])); $jk=(string)($_POST['jk'] ?? ($siswa['jk'] ?? '')); $no_hp=trim((string)($_POST['no_hp'] ?? ($siswa['no_hp'] ?? ''))); $status=(string)($_POST['status'] ?? $siswa['status']);
if ($_SERVER['REQUEST_METHOD']==='POST') { require_valid_csrf(); if($nis===''||$nama==='')$errors[]='NIS dan nama wajib diisi.'; if(!in_array($jk,['','L','P'],true))$errors[]='Jenis kelamin tidak valid.'; if(!in_array($status,['aktif','lulus','nonaktif'],true))$errors[]='Status tidak valid.'; if(!$errors){try{$st=$pdo->prepare("UPDATE siswa SET nis=?, nisn=NULLIF(?, ''), nama=?, jk=NULLIF(?, ''), no_hp=NULLIF(?, ''), status=? WHERE id=?");$st->execute([$nis,$nisn,$nama,$jk,$no_hp,$status,$id]);siswa_audit($pdo,'UPDATE',$id,'Mengubah data siswa '.$nama);redirect('siswa/detail.php?id='.$id.'&saved=1');}catch(PDOException $e){if((int)($e->errorInfo[1]??0)===1062)$errors[]='NIS atau NISN sudah digunakan.';else throw $e;}}}
$page_title='Edit Siswa'; require_once __DIR__.'/../layouts/header.php'; require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Edit Siswa</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content siswa-form-page siswa-edit-page"><div class="page-header"><div><h1>Edit Data Siswa</h1><p>QR permanen tidak berubah saat data identitas diedit.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>siswa/detail.php?id=<?=$id?>">Kembali</a></div><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><div class="form-card"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><label>NIS *<input class="form-control" name="nis" required value="<?=e($nis)?>"></label><label>NISN<input class="form-control" name="nisn" value="<?=e($nisn)?>"></label><label>Nama Lengkap *<input class="form-control" name="nama" required value="<?=e($nama)?>"></label><label>Jenis Kelamin<select class="form-control" name="jk"><option value="">- Pilih -</option><option value="L" <?=$jk==='L'?'selected':''?>>Laki-laki</option><option value="P" <?=$jk==='P'?'selected':''?>>Perempuan</option></select></label><label>No. HP<input class="form-control" name="no_hp" value="<?=e($no_hp)?>"></label><label>Status<select class="form-control" name="status"><option value="aktif" <?=$status==='aktif'?'selected':''?>>Aktif</option><option value="lulus" <?=$status==='lulus'?'selected':''?>>Lulus</option><option value="nonaktif" <?=$status==='nonaktif'?'selected':''?>>Nonaktif</option></select></label></div><div class="form-actions"><button class="btn btn-success btn-save">Simpan Perubahan</button></div></form></div></section></main><?php require_once __DIR__.'/../layouts/footer.php'; ?>
